def validate_record(record):
    if not isinstance(record, dict):
        raise ValueError("Expected a record dictionary")
    record_id = record.get("id")
    duration = record.get("duration")
    success = record.get("success")
    if not isinstance(record_id, str) or not record_id.strip():
        raise ValueError("Expected a nonempty id")
    if type(duration) not in (int, float) or duration < 0:
        raise ValueError("Expected a nonnegative numeric duration")
    if not isinstance(success, bool):
        raise ValueError("Expected boolean success")
    return {"id": record_id.strip(), "duration": float(duration), "success": success}

